function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function autoReview(info) {
  const stars = info.stars || 0;
  const hot = clamp(Math.round(Math.log10(stars + 1) * 1.2 * 10) / 10, 1, 10);
  const days = Math.max(0, (Date.now() - new Date(info.updated + 'T00:00:00Z').getTime()) / 86400000);
  const active = days <= 7 ? 9.5 : days <= 30 ? 8.5 : days <= 90 ? 7.0 : 5.5;
  const docs = (info.description || '').length > 40 ? 7.0 : 6.0;
  const easy = 7.0;
  const score = clamp(Math.round((hot * 0.35 + active * 0.35 + docs * 0.15 + easy * 0.15) * 10) / 10, 5.0, 9.5);
  return {
    score: score,
    tagline: (info.description || '暂无简介。'),
    intro: '该插件暂无人为撰写的深度评测,以下内容由启动器根据 GitHub 数据自动生成:Star 数、最近更新、开源协议等指标的综合评估,仅供参考。',
    pros: [
      stars >= 1000 ? ('GitHub 热度高: ' + stars + ' Star') : '社区规模尚小,仍在成长',
      days <= 30 ? '近期仍在活跃更新' : '近期更新放缓',
      info.license ? ('开源协议明确: ' + info.license) : '未标注明确开源协议,商用前请确认',
    ],
    cons: [
      '暂无深度评测与用户口碑数据',
      stars < 100 ? '使用前建议自行评估代码质量' : '自动评分不代表实际体验',
    ],
    audience: '建议先到 GitHub 查看 README 与 Issue,再决定是否安装。',
    comments: ['自动评测仅供参考,欢迎安装后回来分享体验。'],
    dims: { hot: hot, active: active, docs: docs, easy: easy },
    auto: true,
  };
}

function findPluginInfo(repo) {
  const all = pluginCatalog.trending.concat(pluginCatalog.newest, pluginCatalog.uiThemes);
  for (const item of all) if (item.name === repo) return item;
  return null;
}
async function getPluginDetail(repo) {
  await refreshPluginCatalog(false);
  let info = findPluginInfo(repo);
  if (!info) {
    try {
      const extra = await new Promise((resolve, reject) => {
        https.get('https://api.github.com/repos/' + repo, {
          headers: GH_AUTH_HEADERS,
        }, res => {
          let body = '';
          res.on('data', c => { body += c; });
          res.on('end', () => {
            if (res.statusCode !== 200) return reject(new Error('HTTP ' + res.statusCode));
            try { resolve(JSON.parse(body)); } catch (e) { reject(e); }
          });
        }).on('error', reject);
      });
      info = {
        name: repo,
        description: String(extra.description || '').slice(0, 140),
        stars: extra.stargazers_count || 0,
        html_url: extra.html_url || 'https://github.com/' + repo,
        updated: String(extra.pushed_at || '').slice(0, 10),
      };
    } catch (e) {}
  }
  const review = PLUGIN_REVIEWS[repo] || autoReview(info || { description: '', stars: 0, updated: '' });
  return {
    repo: repo,
    info: info || {
      name: repo, description: '', stars: 0,
      html_url: 'https://github.com/' + repo, updated: '',
    },
    review: review,
  };
}

// ================================================================ 插件预览图
const pluginPreviewCache = {};
const ogFallback = (repo) => 'https://opengraph.githubassets.com/1/' + repo;

function fetchText(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'dsh-launcher/' + VERSION } }, res => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return fetchText(new URL(res.headers.location, url).toString()).then(resolve, reject);
      }
      if (res.statusCode !== 200) {
        res.resume();
        return reject(new Error('HTTP ' + res.statusCode));
      }
      let body = '';
      res.on('data', c => { body += c; });
      res.on('end', () => resolve(body));
    }).on('error', reject);
  });
}

function extractFirstImage(md, repo, branch) {
  const re = /!\[[^\]]*\]\(([^)\s]+)(?:\s+"[^"]*")?\)|<img[^>]+src=["']([^"']+)["']/g;
  let m;
  while ((m = re.exec(md))) {
    const raw = (m[1] || m[2] || '').trim();
    if (!raw) continue;
    if (/badge|shields\.io|simpleicons|badgen/i.test(raw)) continue;
    let url = raw;
    if (!/^https?:/.test(url)) {
      url = 'https://raw.githubusercontent.com/' + repo + '/' + branch + '/' + url.replace(/^\.?\//, '');
    }
    return url;
  }
  return null;
}

const previewImageCache = {};

function fetchBinary(url) {
  return new Promise((resolve, reject) => {
    const u = new URL(url);
    const lib = u.protocol === 'https:' ? https : http;
    const req = lib.get(u, { headers: { 'User-Agent': 'dsh-launcher/' + VERSION } }, res => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        return fetchBinary(new URL(res.headers.location, u).toString()).then(resolve, reject);
      }
      if (res.statusCode !== 200) {
        res.resume();
        return reject(new Error('HTTP ' + res.statusCode));
      }
      const chunks = [];
      let size = 0;
      res.on('data', c => {
        size += c.length;
        if (size > 6 * 1024 * 1024) { req.destroy(); return reject(new Error('image too large')); }
        chunks.push(c);
      });
      res.on('end', () => resolve(Buffer.concat(chunks)));
    });
    req.on('error', reject);
    req.setTimeout(20000, () => req.destroy(new Error('image timeout')));
  });
}

function guessContentType(url, buf) {
  if (buf.length >= 8 && buf[0] === 0x89 && buf[1] === 0x50) return 'image/png';
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8) return 'image/jpeg';
  if (buf.length >= 3 && buf[0] === 0x47 && buf[1] === 0x49 && buf[2] === 0x46) return 'image/gif';
  if (buf.length >= 4 && buf[0] === 0x52 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x46) return 'image/webp';
  const ext = String(url.split('?')[0].split('.').pop() || '').toLowerCase();
  if (ext === 'svg') return 'image/svg+xml';
  if (ext === 'png') return 'image/png';
  if (ext === 'jpg' || ext === 'jpeg') return 'image/jpeg';
  if (ext === 'gif') return 'image/gif';
  if (ext === 'webp') return 'image/webp';
  return 'application/octet-stream';
}

async function getPluginPreviewImage(repo) {
  const now = Date.now();
  const imageUrl = await getPluginPreview(repo);
  const hit = previewImageCache[imageUrl];
  if (hit && now - hit.at < 60 * 60 * 1000) return { buf: hit.buf, ct: hit.ct };
  const buf = await fetchBinary(imageUrl);
  const ct = guessContentType(imageUrl, buf);
  previewImageCache[imageUrl] = { buf: buf, ct: ct, at: now };
  return { buf: buf, ct: ct };
}

async function getPluginPreview(repo) {
  const now = Date.now();
  const hit = pluginPreviewCache[repo];
  if (hit && now - hit.at < 60 * 60 * 1000) return hit.image;
  let image = null;
  for (const branch of ['main', 'master']) {
    try {
      const md = await fetchText('https://raw.githubusercontent.com/' + repo + '/' + branch + '/README.md');
      image = extractFirstImage(md, repo, branch);
      if (image) break;
    } catch (e) {}
  }
  const final = image || ogFallback(repo);
  pluginPreviewCache[repo] = { image: final, at: now };
  return final;
}

